/* The per-particle draw context is the leading member: the particle
 * drawers take &context->draw, and the list-level fields follow it. */
typedef struct SvParticleListCfContext {
    SvParticleDrawContext draw;
    unsigned char unmodeled_18[8];
    int schedulerVariant;
} SvParticleListCfContext;

typedef struct SvBattleEffectData {
    unsigned char unmodeled_00[0x30];
    Quadword packetInfo;
    unsigned char unmodeled_40[0x1DC];
    float scaleMultiplier;
    unsigned char unmodeled_220[4];
    unsigned int flags;
    unsigned char unmodeled_228[4];
    unsigned int partialFlags;
} SvBattleEffectData;

typedef struct SvImageChunk {
    unsigned int byteSize;
    unsigned int storageSize;
    short kind;
    unsigned short typeFlags;
    short width;
    unsigned short height;
    short bitsPerPixel;
    unsigned short packClass;   /* never read: 0 default.esp, 1 character and enemy packs, 2 weapons, 4 cf_def.esp */
    char name[0x2c];
    char data[1];
} SvImageChunk;

typedef struct SvClutChunk {
    unsigned char unmodeled_00[10];
    unsigned short typeFlags;
    short width;
    unsigned short height;
    unsigned short bitsPerPixel;
    unsigned short packClass;   /* unread, see SvImageChunk */
    char name[44];
    unsigned char data[1];
} SvClutChunk;

typedef struct SvResourceChunk {
    unsigned int byteSize;
    unsigned char unmodeled_04[4];
    short kind;
    unsigned short typeFlags;
    char payload[0x34];
} SvResourceChunk;

typedef struct SvResourceChunkFile {
    struct SvResourceChunk *firstChunk;
} SvResourceChunkFile;

